package mx.taller.workshop;
import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*; import java.nio.file.*;
@RestController @Validated @RequestMapping("/api/taller") public class TallerController {
 private final TallerRepository repo; private final CodigoPostalService codigos; private final Path uploads;
 public TallerController(TallerRepository r,CodigoPostalService c,@Value("${app.upload-dir:./uploads}") String dir){repo=r;codigos=c;uploads=Path.of(dir).toAbsolutePath().normalize();}
 @GetMapping public Map<String,Boolean> estado(){return Map.of("configurado",repo.existsByActivoTrue());}
 @GetMapping("/datos") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public Map<String,Object> datos(){Optional<Taller> resultado=repo.findFirstByActivoTrue();if(resultado.isEmpty())return Map.of("configurado",false);Taller t=resultado.get();Map<String,Object> datos=new LinkedHashMap<>();datos.put("configurado",true);datos.put("rfc",t.getRfc());datos.put("nombreComercial",t.getNombreComercial());datos.put("calle",t.getCalle());datos.put("codigoPostal",t.getCodigoPostal());datos.put("colonia",t.getColonia());datos.put("municipio",t.getMunicipio());datos.put("estado",t.getEstado());datos.put("tieneFotografia",t.getFotografia()!=null);return datos;}
 @GetMapping("/codigo-postal/{cp}") @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA')") public Map<String,Object> codigoPostal(@PathVariable @jakarta.validation.constraints.Pattern(regexp="^\\d{5}$") String cp){return codigos.consultar(cp);}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public Map<String,Object> guardar(@Valid @RequestPart("datos") TallerDto d,@RequestPart(value="fotografia",required=false) MultipartFile foto)throws Exception {Taller t=repo.findFirstByActivoTrue().orElseGet(Taller::new);t.actualizar(d.rfc(),d.nombreComercial(),d.calle(),d.codigoPostal(),d.colonia(),d.municipio(),d.estado());if(foto!=null&&!foto.isEmpty()){validarFoto(foto);Path folder=uploads.resolve("taller");Files.createDirectories(folder);String name=UUID.randomUUID()+("image/png".equals(foto.getContentType())?".png":".jpg");Path target=folder.resolve(name).normalize();if(!target.startsWith(folder))throw new IllegalArgumentException("Ruta inválida");foto.transferTo(target);t.setFotografia(target.toString());}t=repo.save(t);return Map.of("id",t.getId(),"mensaje","Taller configurado");}
 @GetMapping("/foto") @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA','MECANICO')") public ResponseEntity<Resource> foto(){Taller t=repo.findFirstByActivoTrue().orElseThrow(()->new IllegalArgumentException("No hay taller configurado"));return imagen(t.getFotografia());}
 private ResponseEntity<Resource> imagen(String path){try{if(path==null)throw new IllegalArgumentException("No hay fotografía");Path p=Path.of(path).toAbsolutePath().normalize();if(!p.startsWith(uploads))throw new IllegalArgumentException("Ruta de archivo inválida");String type=p.toString().toLowerCase(Locale.ROOT).endsWith(".png")?"image/png":"image/jpeg";return ResponseEntity.ok().contentType(MediaType.parseMediaType(type)).header(HttpHeaders.CACHE_CONTROL,"private, max-age=3600").body(new FileSystemResource(p));}catch(IllegalArgumentException e){throw e;}}
 public static void validarFoto(MultipartFile f)throws Exception{if(f.getSize()>15L*1024*1024)throw new IllegalArgumentException("La fotografía debe pesar máximo 15 MB");String c=f.getContentType();byte[] b=f.getBytes();boolean png="image/png".equals(c)&&b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71;boolean jpg="image/jpeg".equals(c)&&b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;if(!png&&!jpg)throw new IllegalArgumentException("Solo se permiten fotografías JPG/PNG válidas");}
}
